        value_data_credit_amount = data_actual['data']['credit_amount']
        value_data_exchange_rate_credit_ac_bcy = data_actual['data']['exchange_rate_credit_ac_bcy']
        value_data_amount_to_credit_bcy = data_actual['data']['amount_to_credit_bcy']
